var c = new LabPttController { RequireGrant = true };
c.Press(0);
int e = c.Epoch;
c.Ready(e, 10);       // WaitingGrant：忽略
c.Grant(e, 20);       // Keying：PTT 要求成立
c.Ready(e, 40);       // Tx：本地音訊閘門開
c.Release(50);
c.Ready(e, 60);       // 已結束：忽略

var c = new LabPttController { RequireGrant = true };
c.Press(0); int old = c.Epoch;
c.Release(10); c.Press(20);
c.Grant(old, 30);          // 舊身份：仍 WaitingGrant
c.Grant(c.Epoch, 40);      // 當前身份：進入 Keying
c.Ready(c.Epoch, 50);      // 合法設備回報才進 Tx
